def update_tests() -> None:
    path = ROOT / "tests/python/test_gap_register.py"
    text = path.read_text(encoding="utf-8")
    if "G-TEAM-001" not in text:
        raise SystemExit("tests/python/test_gap_register.py: expected legacy G-TEAM cases")
    path.write_text(text.replace("G-TEAM-001", "G-IB-001"), encoding="utf-8")


def remove_merge_queue_events() -> None:
    workflow_root = ROOT / ".github/workflows"
    for path in sorted(workflow_root.glob("*.yml")):
        text = path.read_text(encoding="utf-8")
        text = re.sub(
            r"(?m)^  merge_group:\n(?:    [^\n]*\n)+",
            "",
            text,
        )
        path.write_text(text, encoding="utf-8")


